"""Decode an image emitted by the C++ program and re-derive its FIB."""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ref import build_graph, norm

def w2i(w): return int(w, 16)

def decode(img, verbose=False):
    """Walk the packed graph and return the set of (prefix, len, hop)."""
    problems = []
    # per-stage coverage
    covered = {s: [0]*img['cells'][s] for s in range(11)}
    for s in range(11):
        if len(img['banks'][s]) != (img['cells'][s]+1)//2:
            problems.append('bank size stage %d' % s)
    if img['bitmaps'] != sorted(set(img['bitmaps'])):
        problems.append('bitmaps not sorted/unique')
    for f in ('front16','front64'):
        keys = [e[0] for e in img[f]]
        if keys != sorted(set(keys)):
            problems.append('%s not sorted' % f)
    pats = [int(x,16) for x in img['bitmaps']]

    def read(stage, cell, bulk, origin, level, region):
        s = stage; c = cell
        if c >= img['cells'][s]: problems.append('cell out of range'); return []
        row = w2i(img['banks'][s][c//2])
        off = 128*(c % 2)
        def g(p, n): return (row >> (off+p)) & ((1<<n)-1 if n < 64 else (1<<64)-1)
        t = g(0,3)
        if t < 1 or t > 5: problems.append('bad type'); return []
        ordinary = 1 if t in (1,4) else 2
        span = 2 if bulk else ordinary
        if span == 2 and c % 2: problems.append('full at odd cell')
        if c + span > img['cells'][s]: problems.append('span overflow')
        for i in range(span):
            if covered[s][c+i]: problems.append('cell covered twice')
            covered[s][c+i] = 1
        if span == 2 and ordinary == 1 and (row >> 128) != 0:
            problems.append('bulk half padding nonzero')
        depth = origin + 6*level
        bmp = g(3,22)
        out = []
        if t in (4,5):
            for i in range(1 if t==4 else 2):
                frag = g(25+94*i, 64); rel = g(25+94*i+64, 8); hop = g(25+94*i+72, 22)
                if hop == 4194303: problems.append('inline hop null')
                if origin == 0: lo, hi = 0, 16
                elif origin == 16: lo, hi = 1, 48
                else: lo, hi = 1, 64
                if rel < lo or rel > hi: problems.append('rel range')
                if frag & ((1<<(64-rel))-1 if rel < 64 else 0): problems.append('host bits')
                if origin + rel < depth: problems.append('short prefix')
                if origin == 0: p = (frag, rel)
                elif origin == 16:
                    v = frag >> (64-rel)
                    p = (region | (v << (48-rel)), 16+rel)
                else:
                    p = (region | frag, 64+rel) if False else ((region | (frag & 0)), 64+rel)
                    # region hi holds the key; lo is the fragment
                    p = ((region & ((1<<64)-1)) | frag, 64+rel)
                    p = (((region >> 64) << 64) | frag, 64+rel)
                if (p[0] >> (128-p[1])) << (128-p[1]) != p[0]: problems.append('not normalized')
                if p[0] >> (128-depth) << (128-depth) != region: problems.append('not in region')
                out.append((p[0], p[1], hop))
            if t == 5 and out[0][:2] == out[1][:2]: problems.append('type5 dup')
        else:
            bid = g(25,16); base = g(41,22)
            if bid >= len(pats): problems.append('bitmap id'); return out
            bm = pats[bid]
            if bm & 1: problems.append('ni bit0')
            cnt = bin(bm).count('1')
            if cnt == 0 and base != 0: problems.append('empty ni base')
            if base + cnt > len(img['nexthops']): problems.append('ni range')
            rank = 0
            for pos in range(1,64):
                if (bm >> pos) & 1:
                    l = pos.bit_length()-1
                    v = pos - (1<<l)
                    if origin + 6*level + l > (16 if origin==0 else 64 if origin==16 else 128):
                        problems.append('ni pos too long')
                    val = region | (v << (128-depth-l))
                    out.append((val, depth+l, img['nexthops'][base+rank]))
                    rank += 1
            kids = []
            if t in (1,2):
                n = 2 if t == 1 else 6
                seen_abs = False; prev = -1; present = 0
                for i in range(n):
                    v = g(63+32*i, 32)
                    if v == (15<<6): seen_abs = True; continue
                    if seen_abs: problems.append('absent not last')
                    key = v & 0x3F; st = (v>>6)&0xF; cl = v >> 10
                    if st >= 11 or st >= s: problems.append('child stage')
                    if key <= prev: problems.append('child key order')
                    prev = key; present += 1
                    kids.append((key, st, cl, False))
                if t == 2 and present < 3: problems.append('type2 too few children')
                if t == 1 and present > 2: problems.append('type1 too many')
                if g(63+32*n, 1): problems.append('reserved type12')
            else:
                bmap = g(63,64); bbase = g(127,22); bstage = g(149,4)
                for i in range(3):
                    v = g(153+32*i, 32)
                    if v == (15<<6): continue
                    key = v & 0x3F; st = (v>>6)&0xF; cl = v >> 10
                    if st >= 11 or st >= s: problems.append('direct stage')
                    if bmap & (1<<key): problems.append('direct/bulk overlap')
                    kids.append((key, st, cl, False))
                if g(249,7): problems.append('reserved type3')
                bc = bin(bmap).count('1')
                if bc < 4: problems.append('bulk too few')
                if bbase % 2: problems.append('bulk base odd')
                if bstage >= 11 or bstage >= s: problems.append('bulk stage')
                if bbase + 2*bc > img['cells'][bstage]: problems.append('bulk overflow')
                for k in range(64):
                    if (bmap >> k) & 1:
                        rank = bin(bmap & ((1<<k)-1)).count('1')
                        kids.append((k, bstage, bbase + 2*rank, True))
            for (key, st, cl, bulkf) in kids:
                cr = region | (key << (128-depth-6))
                sub = read(st, cl, bulkf, origin, level+1, cr)
                out.extend(sub)
        return out

    allp = []
    if img['root'] is not None:
        allp.extend(read(img['root'][0], img['root'][1], False, 0, 0, 0))
    for e in img['front16']:
        allp.extend(read(e[1], e[2], False, 16, 0, e[0] << 112))
    for e in img['front64']:
        allp.extend(read(e[1], e[2], False, 64, 0, e[0] << 64))
    for s in range(11):
        if any(x == 0 for x in covered[s]): problems.append('uncovered cell stage %d' % s)
        if img['cells'][s] % 2 == 1 and img['banks'][s]:
            if w2i(img['banks'][s][-1]) >> 128: problems.append('final padding nonzero')
    # NI tiling
    return allp, problems

def check_image(img, fib, tag=''):
    allp, problems = decode(img)
    got = set((p, l) for p, l, h in allp)
    want = set(fib)
    if got != want:
        problems.append('FIB mismatch: missing %d extra %d' % (len(want-got), len(got-want)))
    hops = {}
    for p,l,h in allp:
        if (p,l) in hops and hops[(p,l)] != h: problems.append('hop conflict')
        hops[(p,l)] = h
    for (p,l),h in fib.items():
        if hops.get((p,l)) != h: problems.append('hop mismatch %x/%d' % (p,l))
    # BMP check
    root0, f16, f64, pool = build_graph(fib)
    def walk(gn, img, loc, origin, region, level, depth):
        pass
    if problems:
        print('IMAGE PROBLEMS', tag, problems[:8])
    return problems

if __name__ == '__main__':
    import random, subprocess
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 20
    bad = 0
    for it in range(n):
        fib = {}
        npfx = rng.choice([1,3,10,50,200,700])
        for _ in range(npfx):
            a = '%032x' % rng.getrandbits(128)
            l = rng.choice([0,1,16,17,32,48,64,65,96,128, rng.randint(0,128)])
            fib[(norm(a,l), l)] = rng.randint(0,4194302)
        ops = [["put", '%032x' % p, l, h] for (p,l),h in fib.items()]
        ops.append(["save"])
        r = subprocess.run([sys.executable, '/workspace/run.py'],
                           input=json.dumps({"cases":[{"ops":ops}]}).encode(),
                           capture_output=True, cwd='/workspace')
        resp = json.loads(r.stdout.decode())
        img = resp['results'][0]['snapshots'][0]
        pr = check_image(img, fib, 'iter %d' % it)
        if pr: bad += 1
    print('verify failures:', bad)
    sys.exit(1 if bad else 0)
